import re


def _norm(s):
    return re.sub(r"\s+", " ", str(s or "").replace("\u200c", " ").replace("ي", "ی").replace("ك", "ک")).strip()


def fill_managements(apps, schema_editor):
    """هر نام مدیریتِ موجود در استراتژی‌های وظیفه‌ای و OKR را به یک ردیف Management وصل می‌کند.
    هیچ ردیفی پاک یا جابه‌جا نمی‌شود؛ فقط FK پر می‌شود و متن نام عیناً می‌ماند."""
    Management = apps.get_model("strategic", "Management")
    FS = apps.get_model("strategic", "FunctionalStrategy")
    OKR = apps.get_model("strategic", "OKRObjective")
    cache = {}

    def get(unit_id, name):
        name = (name or "").strip()
        if not unit_id or not name:
            return None
        key = (unit_id, _norm(name))
        if key not in cache:
            cache[key] = Management.objects.create(org_unit_id=unit_id, name=name)
        return cache[key]

    for fs in FS.objects.all().order_by("id"):
        m = get(fs.org_unit_id, fs.management)
        if m:
            FS.objects.filter(pk=fs.pk).update(management_ref=m, management=m.name)
    for o in OKR.objects.filter(level="management").order_by("id"):
        m = get(o.org_unit_id, o.management)
        if m:
            OKR.objects.filter(pk=o.pk).update(management_ref=m, management=m.name)


